//! Casper protocol domain types + wire conversion.
//!
//! Mirrors `models/src/main/scala/coop/rchain/casper/protocol/CasperMessage.scala`. The scalapb
//! `*Proto` types (generated by prost from `proto/casper.proto`) are kept private; these hand-written
//! domain types are the public API and carry `from(&Proto)` / `to_proto(&self)`. Sorting for
//! deterministic serialization (Law 16) happens here, at the domain layer, using `BTreeSet`/`BTreeMap`
//! (see `BlockMessage::to_proto`).

use std::collections::{BTreeMap, BTreeSet};

use prost::Message as _;
use rchain_crypto::hash::blake2b256_hash::Blake2b256Hash;
use rchain_shared::refined::{BlockHeight, NonNegI64, SeqNum};
use rchain_shared::serialize::Serialize;

use crate::block::state_hash::StateHash;
use crate::block_hash::BlockHash;
use crate::block_metadata::SlashSeverity;
use crate::casper::protocol::deploy_service::DeployInfo;
use crate::proto::casper::PCost as PCostProto;
use crate::proto::casper::*;
use crate::validator::Validator;
use rchain_shared::base16;

// -------------------------------------------------------------------------------------------------
// Cost
// -------------------------------------------------------------------------------------------------

/// Phantom/execution cost (port of `PCost`).
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct PCost {
    pub cost: u64,
}

impl PCost {
    pub fn from_proto(p: &PCostProto) -> Self {
        Self { cost: p.cost }
    }
    pub fn to_proto(&self) -> PCostProto {
        PCostProto { cost: self.cost }
    }
}

// -------------------------------------------------------------------------------------------------
// Deploy data
// -------------------------------------------------------------------------------------------------

/// Deploy data (port of the `DeployData` case class; the deployer/signature live in
/// [`SignedDeployData`]).
#[derive(Clone, Debug, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct DeployData {
    pub term: String,
    pub timestamp: i64,
    pub phlo_price: i64,
    pub phlo_limit: i64,
    pub valid_after_block_number: i64,
    pub shard_id: String,
    /// Binary attachments (RCHIP #39), hex-encoded in JSON. They are part of the signed deploy data
    /// and are exposed to rholang as `rho:attachment:1`, `rho:attachment:2`, … (1-based, yielding a
    /// `ByteArray`). Empty for an ordinary deploy — which still encodes exactly as before, so
    /// existing signatures and deploy ids are unchanged.
    #[serde(
        default,
        skip_serializing_if = "Vec::is_empty",
        with = "hex_attachments"
    )]
    pub attachments: Vec<Vec<u8>>,
}

/// Serde helper: attachments are hex strings in JSON, the API convention for bytes elsewhere
/// (`deployer`, `signature`, hashes).
mod hex_attachments {
    use serde::{Deserialize, Deserializer, Serializer};

    pub fn serialize<S: Serializer>(value: &[Vec<u8>], s: S) -> Result<S::Ok, S::Error> {
        let hex: Vec<String> = value
            .iter()
            .map(|bytes| rchain_shared::base16::encode(bytes))
            .collect();
        s.collect_seq(hex)
    }

    pub fn deserialize<'de, D: Deserializer<'de>>(d: D) -> Result<Vec<Vec<u8>>, D::Error> {
        let hex = Vec::<String>::deserialize(d)?;
        hex.into_iter()
            .map(|h| {
                rchain_shared::base16::decode(&h)
                    .ok_or_else(|| serde::de::Error::custom("attachment is not valid hex"))
            })
            .collect()
    }
}

impl DeployData {
    /// The total phlo charge (`phlo_limit * phlo_price`). Returns `None` on overflow rather than
    /// wrapping (a wrapped charge would bypass cost accounting). Computed in `i128` so the product
    /// cannot overflow before the `i64` range check.
    ///
    /// **The sign is checked here, and this is the only place it can enter** (AUDIT C109). `phlo_limit`
    /// is `int64` on the wire (`casper.proto`, `DeployDataProto.phlo_limit`), and the charge is a
    /// *debit*: the amount flows to `native.pre_charge`, which subtracts it from the deployer's vault.
    /// A negative limit made that subtraction an **addition** — `balance - (-n) == balance + n` — so a
    /// deploy with `phlo_limit = -100, phlo_price = 1` credited its own deployer 100 REV out of
    /// nothing, while `credit_pos_vault` no-opped on the negative amount and left the staking vault
    /// untouched. The ingress guard at `casper::api::block_api_impl` caught the deploy path, but this
    /// function is what **block validation and replay** call, so a *peer's* block carried the negative
    /// limit straight through to the charge.
    ///
    /// Returning `Option<NonNegI64>` is the fix rather than adding a guard at each caller: the callers
    /// already treat `None` as a hard error ("phlo charge overflow"), the type carries the invariant to
    /// `pre_charge` and on into the vault arithmetic, and a negative limit is now unrepresentable one
    /// step after the wire instead of representable all the way to the balance.
    pub fn total_phlo_charge(&self) -> Option<NonNegI64> {
        let product = (self.phlo_limit as i128).checked_mul(self.phlo_price as i128)?;
        let charge = i64::try_from(product).ok()?;
        NonNegI64::try_from(charge).ok()
    }

    fn from_proto_data(p: &DeployDataProto) -> Self {
        Self {
            term: p.term.clone(),
            timestamp: p.timestamp,
            phlo_price: p.phlo_price,
            phlo_limit: p.phlo_limit,
            valid_after_block_number: p.valid_after_block_number,
            shard_id: p.shard_id.clone(),
            attachments: p.attachments.clone(),
        }
    }

    fn to_proto_data(&self) -> DeployDataProto {
        DeployDataProto {
            term: self.term.clone(),
            timestamp: self.timestamp,
            phlo_price: self.phlo_price,
            phlo_limit: self.phlo_limit,
            valid_after_block_number: self.valid_after_block_number,
            shard_id: self.shard_id.clone(),
            attachments: self.attachments.clone(),
            ..DeployDataProto::default()
        }
    }
}

impl Serialize<DeployData> for DeployData {
    fn encode(a: &DeployData) -> Vec<u8> {
        a.to_proto_data().encode_to_vec()
    }

    fn decode(bytes: &[u8]) -> Result<DeployData, String> {
        DeployDataProto::decode(bytes)
            .map(|p| DeployData::from_proto_data(&p))
            .map_err(|e| e.to_string())
    }
}

/// A signed deploy (the wire form of `Signed[DeployData]`).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SignedDeployData {
    pub data: DeployData,
    pub deployer: Vec<u8>,
    pub sig: Vec<u8>,
    pub sig_algorithm: String,
}

impl SignedDeployData {
    pub fn from_proto(p: &DeployDataProto) -> Self {
        SignedDeployData {
            data: DeployData::from_proto_data(p),
            deployer: p.deployer.clone(),
            sig: p.sig.clone(),
            sig_algorithm: p.sig_algorithm.clone(),
        }
    }

    pub fn to_proto(&self) -> DeployDataProto {
        DeployDataProto {
            deployer: self.deployer.clone(),
            sig: self.sig.clone(),
            sig_algorithm: self.sig_algorithm.clone(),
            ..self.data.to_proto_data()
        }
    }

    /// Verify the signature over the deploy data, byte-identical to the HTTP path
    /// (`node/src/api/conversion.rs::to_signed_deploy`). Returns `false` on any failure
    /// (unknown algorithm, malformed key/sig, or mismatched signature).
    pub fn verify_signature(&self) -> bool {
        let Some(alg) =
            rchain_crypto::signatures::signatures_alg::from_algorithm(&self.sig_algorithm)
        else {
            return false;
        };
        let serialized = <DeployData as Serialize<DeployData>>::encode(&self.data);
        let hash = rchain_crypto::signatures::signed::signature_hash(alg.name(), &serialized);
        let pk = rchain_crypto::public_key::PublicKey::new(self.deployer.clone());
        alg.verify(&hash, &self.sig, pk.bytes())
    }

    pub fn to_bytes(&self) -> Vec<u8> {
        self.to_proto().encode_to_vec()
    }

    pub fn from_bytes(bytes: &[u8]) -> Result<Self, crate::errors::ModelsError> {
        let proto = DeployDataProto::decode(bytes)
            .map_err(|e| crate::errors::ModelsError::Decode(e.to_string()))?;
        Ok(Self::from_proto(&proto))
    }
}

