/// A processed deploy (port of `ProcessedDeploy`).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ProcessedDeploy {
    pub deploy: SignedDeployData,
    pub cost: PCost,
    pub deploy_log: Vec<Event>,
    pub is_failed: bool,
    pub system_deploy_error: Option<String>,
}

impl ProcessedDeploy {
    pub fn from_proto(p: &ProcessedDeployProto) -> Result<Self, crate::errors::ModelsError> {
        let deploy = p
            .deploy
            .as_ref()
            .ok_or(crate::errors::ModelsError::Malformed(
                "malformed ProcessedDeploy: missing deploy",
            ))?;
        let deploy_log: Result<Vec<Event>, crate::errors::ModelsError> =
            p.deploy_log.iter().map(Event::from_proto).collect();
        Ok(ProcessedDeploy {
            deploy: SignedDeployData::from_proto(deploy),
            cost: p.cost.as_ref().map(PCost::from_proto).unwrap_or_default(),
            deploy_log: deploy_log?,
            is_failed: p.errored,
            system_deploy_error: if p.system_deploy_error.is_empty() {
                None
            } else {
                Some(p.system_deploy_error.clone())
            },
        })
    }

    pub fn to_proto(&self) -> ProcessedDeployProto {
        ProcessedDeployProto {
            deploy: Some(self.deploy.to_proto()),
            cost: Some(self.cost.to_proto()),
            deploy_log: self.deploy_log.iter().map(Event::to_proto).collect(),
            errored: self.is_failed,
            system_deploy_error: self.system_deploy_error.clone().unwrap_or_default(),
        }
    }

    /// Build the client-facing deploy info (port of `toDeployInfo`).
    pub fn to_deploy_info(&self) -> DeployInfo {
        DeployInfo {
            deployer: base16::encode(&self.deploy.deployer),
            term: self.deploy.data.term.clone(),
            timestamp: self.deploy.data.timestamp,
            sig: base16::encode(&self.deploy.sig),
            sig_algorithm: self.deploy.sig_algorithm.clone(),
            phlo_price: self.deploy.data.phlo_price,
            phlo_limit: self.deploy.data.phlo_limit,
            valid_after_block_number: self.deploy.data.valid_after_block_number,
            cost: self.cost.cost,
            errored: self.is_failed,
            system_deploy_error: self.system_deploy_error.clone().unwrap_or_default(),
        }
    }

    /// The phlo refunded after this deploy: `max(0, phlo_limit − cost) × phlo_price` (port of
    /// `ProcessedDeploy.refundAmount`). Computed in `i128` and clamped to `i64::MAX` so the refund
    /// cannot wrap. Shared by play and replay so the two paths cannot drift (S3).
    ///
    /// **The clamp is at both ends, and `NonNegI64` is why that matters** (AUDIT C109). The doc here
    /// used to say the result was "non-negative by construction", and that was true only while every
    /// input was: `remaining` is clamped to `>= 0` above, but `phlo_price` is a bare `i64` from the
    /// wire, so a negative price made the product negative, `i64::try_from` accepted it, and the
    /// function returned a negative refund — precisely the value `native.refund` guards against. The
    /// guard is the backstop; the type is the fix. Clamping the product at zero as well means the
    /// returned value is non-negative for *every* input, which is what the sentence now claims.
    pub fn refund_amount(&self) -> NonNegI64 {
        let remaining = self
            .deploy
            .data
            .phlo_limit
            .saturating_sub_unsigned(self.cost.cost)
            .max(0) as i128;
        let product = remaining * (self.deploy.data.phlo_price as i128);
        let clamped = i64::try_from(product).unwrap_or(i64::MAX);
        NonNegI64::saturating(clamped)
    }

    /// **The REV this deploy burned**: `cost × phlo_price` — the phlo it consumed, priced. This is
    /// what the staking vault keeps for the deploy once the refund has left, and it is the base the
    /// producer's share is taken from (B2, #150).
    ///
    /// The same shared-by-play-and-replay argument as [`Self::refund_amount`], whose bracketing this
    /// mirrors exactly — `cost` is a `u64` and `phlo_price` a bare `i64` off the wire, so the product
    /// is taken in `i128` and clamped at both ends. It is `charge − refund` whenever neither of those
    /// clamps, which is every deploy that plays normally; where they can disagree the vault's own
    /// arithmetic is authoritative and this is what the *share* is computed from, with the payment
    /// bounded by the share rather than by this value.
    pub fn burned_amount(&self) -> NonNegI64 {
        let product = i128::from(self.cost.cost) * i128::from(self.deploy.data.phlo_price);
        let clamped = i64::try_from(product).unwrap_or(i64::MAX);
        NonNegI64::saturating(clamped)
    }
}

