/// A block message (port of `BlockMessage`).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BlockMessage {
    pub version: i32,
    pub shard_id: String,
    pub block_hash: BlockHash,
    pub block_number: BlockHeight,
    pub sender: Validator,
    pub seq_num: SeqNum,
    pub pre_state_hash: StateHash,
    pub post_state_hash: StateHash,
    pub justifications: Vec<BlockHash>,
    pub bonds: BTreeMap<Validator, NonNegI64>,
    pub rejected_deploys: std::collections::BTreeSet<Vec<u8>>,
    pub rejected_blocks: std::collections::BTreeSet<BlockHash>,
    pub rejected_senders: std::collections::BTreeSet<Vec<u8>>,
    pub state: RholangState,
    pub sig_algorithm: String,
    pub sig: Vec<u8>,
    /// Proposer's wall clock (ms since the Unix epoch) at block creation. Informational only: it is
    /// not a consensus input (validators ignore it); applications read it via `rho:block:data`.
    pub timestamp: i64,
}

impl BlockMessage {
    pub fn from_proto(bm: &BlockMessageProto) -> Result<BlockMessage, crate::errors::ModelsError> {
        let state = bm
            .state
            .as_ref()
            .ok_or(crate::errors::ModelsError::Malformed(
                "malformed BlockMessage: missing state",
            ))?;
        Ok(BlockMessage {
            version: bm.version,
            shard_id: bm.shard_id.clone(),
            block_hash: BlockHash::try_from(bm.block_hash.as_slice())?,
            block_number: BlockHeight::try_from(bm.block_number)
                .map_err(|_| crate::errors::ModelsError::Malformed("negative block number"))?,
            sender: Validator::try_from(bm.sender.as_slice())?,
            seq_num: SeqNum::try_from(bm.seq_num)
                .map_err(|_| crate::errors::ModelsError::Malformed("negative sequence number"))?,
            pre_state_hash: StateHash::try_from(bm.pre_state_hash.as_slice())?,
            post_state_hash: StateHash::try_from(bm.post_state_hash.as_slice())?,
            justifications: bm
                .justifications
                .iter()
                .map(|b| BlockHash::try_from(b.as_slice()))
                .collect::<Result<Vec<BlockHash>, crate::errors::ModelsError>>()?,
            bonds: bm
                .bonds
                .iter()
                .map(|b| {
                    let stake = NonNegI64::try_from(b.stake)
                        .map_err(|_| crate::errors::ModelsError::Malformed("negative bond stake"))?;
                    Ok((Validator::try_from(b.validator.as_slice())?, stake))
                })
                .collect::<Result<_, crate::errors::ModelsError>>()?,
            rejected_deploys: bm.rejected_deploys.iter().cloned().collect(),
            rejected_blocks: bm
                .rejected_blocks
                .iter()
                .map(|b| BlockHash::try_from(b.as_slice()))
                .collect::<Result<std::collections::BTreeSet<BlockHash>, crate::errors::ModelsError>>()?,
            rejected_senders: bm.rejected_senders.iter().cloned().collect(),
            state: RholangState::from_proto(state)?,
            sig_algorithm: bm.sig_algorithm.clone(),
            sig: bm.sig.clone(),
            timestamp: bm.timestamp,
        })
    }

    /// Serialize with sorted justifications/bonds/rejections (Law 16 determinism).
    pub fn to_proto(&self) -> BlockMessageProto {
        let mut justifications: Vec<BlockHash> = self.justifications.clone();
        justifications.sort();
        let mut bonds: Vec<BondProto> = self
            .bonds
            .iter()
            .map(|(validator, stake)| BondProto {
                validator: validator.as_bytes().to_vec(),
                stake: i64::from(*stake),
            })
            .collect();
        bonds.sort_by(|a, b| a.validator.cmp(&b.validator));
        let mut rejected_deploys: Vec<Vec<u8>> = self.rejected_deploys.iter().cloned().collect();
        rejected_deploys.sort();
        let mut rejected_blocks: Vec<BlockHash> = self.rejected_blocks.iter().copied().collect();
        rejected_blocks.sort();
        let mut rejected_senders: Vec<Vec<u8>> = self.rejected_senders.iter().cloned().collect();
        rejected_senders.sort();

        BlockMessageProto {
            version: self.version,
            shard_id: self.shard_id.clone(),
            block_hash: self.block_hash.as_bytes().to_vec(),
            block_number: i64::from(self.block_number),
            sender: self.sender.as_bytes().to_vec(),
            seq_num: i64::from(self.seq_num),
            pre_state_hash: self.pre_state_hash.as_bytes().to_vec(),
            post_state_hash: self.post_state_hash.as_bytes().to_vec(),
            justifications: justifications
                .into_iter()
                .map(|b| b.as_bytes().to_vec())
                .collect(),
            bonds,
            rejected_deploys,
            rejected_blocks: rejected_blocks
                .into_iter()
                .map(|b| b.as_bytes().to_vec())
                .collect(),
            rejected_senders,
            state: Some(self.state.to_proto()),
            sig_algorithm: self.sig_algorithm.clone(),
            sig: self.sig.clone(),
            timestamp: self.timestamp,
        }
    }

    pub fn to_bytes(&self) -> Vec<u8> {
        self.to_proto().encode_to_vec()
    }

    /// **The wire form with the two self-referential fields cleared** — `block_hash` and `sig` — which
    /// is exactly what the content-addressed hash is taken over (`hashBlock`).
    ///
    /// A method here rather than a clone-then-clear at the caller, which is what `proto_util::hash_block`
    /// used to do: the clone deep-copies the whole block, and a block holds up to 255 deploys each with
    /// its term and event log, while the proto construction below copies all of that *again* — so the
    /// clone was pure surplus, paid on every block a node creates and every block it validates (issue
    /// #144's family A, candidate 4). The two fields are cleared on the **proto**, after it is built, so
    /// the bytes are the same bytes: the clearing is a field assignment either way, and `to_proto` reads
    /// neither field into any other.
    pub fn to_bytes_cleared(&self) -> Vec<u8> {
        let mut proto = self.to_proto();
        proto.block_hash = BlockHash::new([0u8; crate::block_hash::LENGTH])
            .as_bytes()
            .to_vec();
        proto.sig = Vec::new();
        proto.encode_to_vec()
    }

    pub fn from_bytes(bytes: &[u8]) -> Result<BlockMessage, crate::errors::ModelsError> {
        let proto = BlockMessageProto::decode(bytes)
            .map_err(|e| crate::errors::ModelsError::Decode(e.to_string()))?;
        BlockMessage::from_proto(&proto)
    }
}

