// -------------------------------------------------------------------------------------------------
// Casper message (sum type)
// -------------------------------------------------------------------------------------------------

/// The sealed `CasperMessage` sum type (port of the Scala `sealed trait CasperMessage`).
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum CasperMessage {
    BlockMessage(BlockMessage),
    BlockRequest(BlockRequest),
    BlockRangeRequest(BlockRangeRequest),
    BlockRange(BlockRange),
    BlockHashMessage(BlockHashMessage),
    HasBlock(HasBlock),
    HasBlockRequest(HasBlockRequest),
    ForkChoiceTipRequest(ForkChoiceTipRequest),
    FinalizedFringe(FinalizedFringe),
    FinalizedFringeRequest(FinalizedFringeRequest),
    StoreItemsMessageRequest(StoreItemsMessageRequest),
    StoreItemsMessage(StoreItemsMessage),
}

/// The sealed `CasperMessageProto` sum type (the scalapb `sealed trait CasperMessageProto`).
#[derive(Clone, Debug, PartialEq)]
pub enum CasperMessageProto {
    BlockMessage(BlockMessageProto),
    BlockRequest(BlockRequestProto),
    BlockRangeRequest(BlockRangeRequestProto),
    BlockRange(BlockRangeProto),
    BlockHashMessage(BlockHashMessageProto),
    HasBlock(HasBlockProto),
    HasBlockRequest(HasBlockRequestProto),
    ForkChoiceTipRequest(ForkChoiceTipRequestProto),
    FinalizedFringe(FinalizedFringeProto),
    FinalizedFringeRequest(FinalizedFringeRequestProto),
    StoreItemsMessageRequest(StoreItemsMessageRequestProto),
    StoreItemsMessage(StoreItemsMessageProto),
}

impl CasperMessage {
    pub fn from_proto(
        cm: &CasperMessageProto,
    ) -> Result<CasperMessage, crate::errors::ModelsError> {
        match cm {
            CasperMessageProto::BlockMessage(m) => {
                Ok(CasperMessage::BlockMessage(BlockMessage::from_proto(m)?))
            }
            CasperMessageProto::BlockRequest(m) => {
                Ok(CasperMessage::BlockRequest(BlockRequest::from_proto(m)?))
            }
            CasperMessageProto::BlockRangeRequest(m) => Ok(CasperMessage::BlockRangeRequest(
                BlockRangeRequest::from_proto(m)?,
            )),
            CasperMessageProto::BlockRange(m) => {
                Ok(CasperMessage::BlockRange(BlockRange::from_proto(m)?))
            }
            CasperMessageProto::BlockHashMessage(m) => Ok(CasperMessage::BlockHashMessage(
                BlockHashMessage::from_proto(m)?,
            )),
            CasperMessageProto::HasBlock(m) => {
                Ok(CasperMessage::HasBlock(HasBlock::from_proto(m)?))
            }
            CasperMessageProto::HasBlockRequest(m) => Ok(CasperMessage::HasBlockRequest(
                HasBlockRequest::from_proto(m)?,
            )),
            CasperMessageProto::ForkChoiceTipRequest(_) => {
                Ok(CasperMessage::ForkChoiceTipRequest(ForkChoiceTipRequest))
            }
            CasperMessageProto::FinalizedFringe(m) => Ok(CasperMessage::FinalizedFringe(
                FinalizedFringe::from_proto(m)?,
            )),
            CasperMessageProto::FinalizedFringeRequest(m) => Ok(
                CasperMessage::FinalizedFringeRequest(FinalizedFringeRequest::from_proto(m)?),
            ),
            CasperMessageProto::StoreItemsMessageRequest(m) => Ok(
                CasperMessage::StoreItemsMessageRequest(StoreItemsMessageRequest::from_proto(m)?),
            ),
            CasperMessageProto::StoreItemsMessage(m) => Ok(CasperMessage::StoreItemsMessage(
                StoreItemsMessage::from_proto(m)?,
            )),
        }
    }

    pub fn to_proto(&self) -> CasperMessageProto {
        match self {
            CasperMessage::BlockMessage(m) => CasperMessageProto::BlockMessage(m.to_proto()),
            CasperMessage::BlockRequest(m) => CasperMessageProto::BlockRequest(m.to_proto()),
            CasperMessage::BlockRangeRequest(m) => {
                CasperMessageProto::BlockRangeRequest(m.to_proto())
            }
            CasperMessage::BlockRange(m) => CasperMessageProto::BlockRange(m.to_proto()),
            CasperMessage::BlockHashMessage(m) => {
                CasperMessageProto::BlockHashMessage(BlockHashMessageProto {
                    hash: m.block_hash.as_bytes().to_vec(),
                    block_creator: m.block_creator.clone(),
                })
            }
            CasperMessage::HasBlock(m) => CasperMessageProto::HasBlock(m.to_proto()),
            CasperMessage::HasBlockRequest(m) => CasperMessageProto::HasBlockRequest(m.to_proto()),
            CasperMessage::ForkChoiceTipRequest(_) => {
                CasperMessageProto::ForkChoiceTipRequest(ForkChoiceTipRequestProto {})
            }
            CasperMessage::FinalizedFringe(m) => CasperMessageProto::FinalizedFringe(m.to_proto()),
            CasperMessage::FinalizedFringeRequest(m) => {
                CasperMessageProto::FinalizedFringeRequest(m.to_proto())
            }
            CasperMessage::StoreItemsMessageRequest(m) => {
                CasperMessageProto::StoreItemsMessageRequest(m.to_proto())
            }
            CasperMessage::StoreItemsMessage(m) => {
                CasperMessageProto::StoreItemsMessage(m.to_proto())
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn block_hash(byte: u8) -> BlockHash {
        BlockHash::new([byte; 32])
    }

    fn validator(byte: u8) -> Validator {
        Validator::new([byte; 65])
    }

    fn empty_block() -> BlockMessage {
        BlockMessage {
            version: 1,
            shard_id: "root".to_string(),
            block_hash: block_hash(0),
            block_number: 0.try_into().unwrap(),
            sender: validator(1),
            seq_num: 0.try_into().unwrap(),
            pre_state_hash: StateHash::new([0u8; 32]),
            post_state_hash: StateHash::new([0u8; 32]),
            justifications: Vec::new(),
            bonds: BTreeMap::new(),
            rejected_deploys: std::collections::BTreeSet::new(),
            rejected_blocks: std::collections::BTreeSet::new(),
            rejected_senders: std::collections::BTreeSet::new(),
            state: RholangState::default(),
            sig_algorithm: "secp256k1".to_string(),
            sig: Vec::new(),
            timestamp: 0,
        }
    }

    /// **`to_bytes_cleared` is the same bytes as the clone-then-clear it replaced** (issue #144's
    /// family A, candidate 4).
    ///
    /// The change is only sound if the two routes agree **byte for byte**: the block's hash is taken
    /// over exactly these bytes, so a field cleared differently would be a different hash, and a
    /// different hash is a chain split. The test builds a block that carries a deploy with a real term
    /// and event log — so the clone being removed was copying something — and requires the two
    /// encodings to be equal, with the uncleared encoding asserted different as the control that the
    /// clearing is doing work at all.
    #[test]
    fn the_cleared_encoding_matches_the_clone_then_clear_it_replaced() {
        let mut block = empty_block();
        block.state.deploys = vec![ProcessedDeploy {
            deploy: SignedDeployData {
                data: DeployData {
                    term: "x".repeat(4096),
                    timestamp: 0,
                    phlo_price: 1,
                    phlo_limit: 100,
                    valid_after_block_number: 0,
                    shard_id: "root".to_string(),
                    attachments: Vec::new(),
                },
                deployer: vec![1u8; 65],
                sig: vec![2u8; 64],
                sig_algorithm: "secp256k1".to_string(),
            },
            cost: PCost { cost: 1 },
            deploy_log: Vec::new(),
            is_failed: false,
            system_deploy_error: None,
        }];
        block.sig = vec![7u8; 64];
        block.block_hash = block_hash(9);

        let mut cleared = block.clone();
        cleared.block_hash = BlockHash::new([0u8; 32]);
        cleared.sig = Vec::new();

        assert_eq!(
            block.to_bytes_cleared(),
            cleared.to_bytes(),
            "the hash is taken over these bytes; a difference here is a different block"
        );
        assert_ne!(
            block.to_bytes(),
            block.to_bytes_cleared(),
            "the control: this block does carry a hash and a signature, so the clearing does work"
        );
    }

    /// **Every `CasperMessage` variant survives its own wire codec.** The tests here round-trip
    /// `BlockMessage` only, so `to_proto`/`from_proto`'s other eight arms — and the
    /// `to_bytes`/`from_bytes` pairs of the standalone request types — had never run. A variant that
    /// dropped a field on the way out, or decoded another variant's field, would compile, send, and
    /// arrive subtly wrong; each row is built, encoded, decoded and compared **whole**, so a dropped
    /// or transposed field fails here rather than surviving as a default. (The `body` corpus is the
    /// same idea one layer down for `BlockMessage`'s bytes; this is the message layer.)
    #[test]
    fn every_message_variant_round_trips_through_its_codec() {
        let cases: Vec<CasperMessage> = vec![
            CasperMessage::BlockRequest(BlockRequest {
                hash: block_hash(1),
            }),
            CasperMessage::BlockHashMessage(BlockHashMessage {
                block_hash: block_hash(7),
                block_creator: vec![9, 8, 7],
            }),
            CasperMessage::HasBlock(HasBlock {
                hash: block_hash(4),
            }),
            CasperMessage::HasBlockRequest(HasBlockRequest {
                hash: block_hash(6),
            }),
            CasperMessage::ForkChoiceTipRequest(ForkChoiceTipRequest),
            CasperMessage::FinalizedFringe(FinalizedFringe {
                hashes: vec![block_hash(1), block_hash(2)],
                state_hash: StateHash::new([3u8; 32]),
                ancestry: Vec::new(),
            }),
            CasperMessage::FinalizedFringeRequest(FinalizedFringeRequest {
                identifier: "peer-1".to_string(),
                trim_state: true,
                include_fringe_metadata: true,
                anchor: None,
            }),
            CasperMessage::StoreItemsMessageRequest(StoreItemsMessageRequest {
                start_path: vec![(Blake2b256Hash::from_bytes([4u8; 32]), Some(2))],
                skip: 3,
                take: 4,
            }),
            CasperMessage::StoreItemsMessage(StoreItemsMessage {
                start_path: vec![(Blake2b256Hash::from_bytes([5u8; 32]), None)],
                last_path: vec![(Blake2b256Hash::from_bytes([6u8; 32]), Some(1))],
                history_items: vec![(Blake2b256Hash::from_bytes([7u8; 32]), vec![1, 2])],
                data_items: vec![(Blake2b256Hash::from_bytes([8u8; 32]), vec![3, 4])],
            }),
        ];
        for case in cases {
            let proto = case.to_proto();
            let back = CasperMessage::from_proto(&proto)
                .unwrap_or_else(|e| panic!("{case:?} did not decode: {e:?}"));
            assert_eq!(back, case, "a variant round trips whole");
        }
    }

    /// A peer that sends a hash that is not 32 bytes must be **refused at decode**, not panicked on
    /// later. `BlockRequest`/`HasBlock`/`HasBlockRequest` carried `Vec<u8>` and were cloned
    /// unchecked, and the handler's first statement called `BlockHash::from_slice`, whose length
    /// assert unwinds. AUDIT R12 converted seven message types and missed these three.
    ///
    /// Each test below is the falsifier for that fix: it asserts `Err` where the tree returned `Ok`
    /// (and the panic followed in the handler).
    #[test]
    fn block_request_with_a_short_hash_is_refused() {
        let proto = CasperMessageProto::BlockRequest(BlockRequestProto {
            hash: vec![1, 2, 3],
        });
        assert!(
            CasperMessage::from_proto(&proto).is_err(),
            "BlockRequest accepted a 3-byte hash; the handler then panics in BlockHash::from_slice"
        );
    }

    #[test]
    fn has_block_with_a_short_hash_is_refused() {
        let proto = CasperMessageProto::HasBlock(HasBlockProto { hash: vec![4, 5] });
        assert!(
            CasperMessage::from_proto(&proto).is_err(),
            "HasBlock accepted a 2-byte hash; the handler then panics in BlockHash::from_slice"
        );
    }

    #[test]
    fn has_block_request_with_a_short_hash_is_refused() {
        let proto = CasperMessageProto::HasBlockRequest(HasBlockRequestProto { hash: vec![6] });
        assert!(
            CasperMessage::from_proto(&proto).is_err(),
            "HasBlockRequest accepted a 1-byte hash; the handler then panics in BlockHash::from_slice"
        );
    }

    /// The same refusal one layer down, at the raw-bytes entry a peer's packet content takes:
    /// `from_bytes` decodes the proto and then runs the checked `from_proto`. This is the closest
    /// test to the socket, and unlike a hand-built byte literal it cannot pass vacuously — the proto
    /// is constructed through the generated type, so the only thing that can make it fail is the
    /// length check under test.
    #[test]
    fn block_request_from_bytes_refuses_a_short_hash() {
        let bytes = BlockRequestProto {
            hash: vec![1, 2, 3],
        }
        .encode_to_vec();
        assert!(
            BlockRequest::from_bytes(&bytes).is_err(),
            "a 3-byte hash decoded from raw bytes; the handler then panics in BlockHash::from_slice"
        );
    }

    /// The fourth ingress R12's follow-up missed. A peer's `BlockMessage` carries this trace, and
    /// the replay path handed the bytes to `Blake2b256Hash::from_byte_array`, whose length assert
    /// unwinds — so the same three bytes that kill the shard through a `BlockRequest` also killed it
    /// through block replay.
    #[test]
    fn event_with_a_short_hash_is_refused() {
        let proto = EventProto {
            event_instance: Some(event_proto::EventInstance::Produce(ProduceEventProto {
                channels_hash: vec![1u8; 32],
                hash: vec![2, 3],
                persistent: false,
                times_repeated: 0,
            })),
        };
        assert!(
            Event::from_proto(&proto).is_err(),
            "a 2-byte event hash decoded; the replay path then panics in Blake2b256Hash::from_byte_array"
        );
    }

    #[test]
    fn block_message_round_trip_preserves_timestamp() {
        // The informational timestamp is carried in the header proto, so every node (and replay)
        // decodes the same value.
        let mut block = empty_block();
        block.timestamp = 1_700_000_000_000;
        let round = BlockMessage::from_bytes(&block.to_bytes()).expect("round trip");
        assert_eq!(round.timestamp, block.timestamp);
    }

    #[test]
    fn law16_to_proto_sorts_justifications() {
        let mut block = empty_block();
        block.justifications = vec![block_hash(3), block_hash(1), block_hash(2)];
        let proto = block.to_proto();
        assert_eq!(
            proto.justifications,
            vec![
                block_hash(1).as_bytes().to_vec(),
                block_hash(2).as_bytes().to_vec(),
                block_hash(3).as_bytes().to_vec(),
            ]
        );
    }

    /// **The wire order of `bonds`/`rejected_blocks` — and the boundary this test is on.** Its
    /// name claimed to witness `to_proto`'s sorts for these two fields; *measured*, it cannot: with
    /// both `bonds.sort_by` and `rejected_blocks.sort()` deleted, this test passes — and so do the
    /// other 155 tests in this crate, so nothing else catches them either. The reason is the types:
    /// both fields are collected from a `BTreeMap`/`BTreeSet`, whose iteration order is already the
    /// sorted order the assertion checks, so the sorts are redundant here and no input can make them
    /// observable. (The *justifications* sort is a real witness — `to_proto_sorts_justifications`
    /// builds an unsorted `Vec` — and it is a different field.)
    ///
    /// So this pins the wire order the block hash depends on, which is worth keeping; what it must
    /// not do is read as evidence for the sorts. The register's Law 16c row carries the boundary:
    /// `Canonical` (justifications sorted) is checked for the field that can be unsorted.
    #[test]
    fn to_proto_keeps_bonds_and_rejections_in_sorted_order() {
        let mut block = empty_block();
        block.bonds = BTreeMap::from([
            (validator(3), 1.try_into().unwrap()),
            (validator(1), 2.try_into().unwrap()),
            (validator(2), 3.try_into().unwrap()),
        ]);
        block.rejected_blocks = [block_hash(9), block_hash(1)].into_iter().collect();
        let proto = block.to_proto();
        // Bonds already iterated in key order (BTreeMap) and then sorted by validator bytes.
        let validators: Vec<u8> = proto.bonds.iter().map(|b| b.validator[0]).collect();
        assert_eq!(validators, vec![1, 2, 3]);
        assert_eq!(
            proto.rejected_blocks,
            vec![
                block_hash(1).as_bytes().to_vec(),
                block_hash(9).as_bytes().to_vec()
            ]
        );
    }

    #[test]
    fn block_message_round_trips() {
        let mut block = empty_block();
        block.justifications = vec![block_hash(1), block_hash(2)];
        block.bonds = BTreeMap::from([(validator(1), 100.try_into().unwrap())]);
        block.rejected_blocks = [block_hash(7)].into_iter().collect();
        let bytes = block.to_bytes();
        let decoded = BlockMessage::from_bytes(&bytes).unwrap();
        assert_eq!(decoded, block);
    }

    #[test]
    fn finalized_fringe_round_trips() {
        let fringe = FinalizedFringe {
            hashes: vec![block_hash(1), block_hash(2)],
            state_hash: StateHash::new([7u8; 32]),
            ancestry: Vec::new(),
        };
        let decoded = FinalizedFringe::from_bytes(&fringe.to_bytes()).unwrap();
        assert_eq!(decoded, fringe);
    }

    /// **The per-block fringe state survives the wire** (AUDIT C188, #139).
    ///
    /// A joining node cannot derive `fringe`/`fringe_state_hash` for the blocks it restores — they are
    /// the *proposer's* own recomputation and are not block fields — so this field is the whole of what
    /// makes a mature join replayable. A codec that dropped it would put every joiner back at the
    /// pre-#139 behaviour with no other symptom, which is why it is pinned as a round trip rather than
    /// left to the devnet to notice.
    ///
    /// The request flag is pinned with it: a responder reads *that* to decide whether to send the
    /// ancestry at all, so a codec that dropped the flag would silently turn the addition off.
    /// A height window round-trips through the wire, and **a hash that is not 32 bytes is refused by
    /// the decoder rather than panicking in the handler** — AUDIT R12's class: three message types
    /// carried raw `Vec<u8>` and the handler's first statement panicked on a short one, so any
    /// connected peer could kill a shard's task. The refinement makes that unconstructible.
    #[test]
    fn a_block_range_round_trips_and_a_short_hash_is_refused() {
        let h1 = BlockHash::new([1u8; 32]);
        let h2 = BlockHash::new([2u8; 32]);
        let range = BlockRange {
            from: 3,
            to: 4,
            hashes: vec![h1, h2],
            tip: 99,
        };
        let decoded = BlockRange::from_bytes(&range.to_bytes()).expect("round trip");
        assert_eq!(decoded, range);

        let req = BlockRangeRequest { from: 3, to: 4 };
        assert_eq!(
            BlockRangeRequest::from_bytes(&req.to_bytes()).expect("round trip"),
            req
        );

        let short = BlockRangeProto {
            from: 3,
            to: 4,
            hashes: vec![vec![7u8; 31]],
            tip: 99,
        };
        assert!(
            BlockRange::from_proto(&short).is_err(),
            "a 31-byte hash is an error, not a panic"
        );
    }

    #[test]
    fn the_fringe_ancestry_round_trips() {
        let fringe = FinalizedFringe {
            hashes: vec![block_hash(2)],
            state_hash: StateHash::new([7u8; 32]),
            ancestry: vec![
                BlockFringe {
                    block_hash: block_hash(1),
                    fringe: BTreeSet::new(),
                    fringe_state_hash: StateHash::new([9u8; 32]),
                },
                BlockFringe {
                    block_hash: block_hash(2),
                    fringe: [block_hash(1)].into_iter().collect(),
                    fringe_state_hash: StateHash::new([8u8; 32]),
                },
            ],
        };
        let decoded = FinalizedFringe::from_bytes(&fringe.to_bytes()).unwrap();
        assert_eq!(decoded, fringe, "the ancestry must survive the wire");

        let req = FinalizedFringeRequest {
            identifier: "joiner".to_string(),
            trim_state: false,
            include_fringe_metadata: true,
            anchor: Some(block_hash(5)),
        };
        let decoded = FinalizedFringeRequest::from_bytes(&req.to_bytes()).unwrap();
        assert_eq!(decoded, req, "and so must the flag that asks for it");
        assert_eq!(
            decoded.anchor,
            Some(block_hash(5)),
            "and the anchor the recovery sync names (C259)"
        );

        // A **request without an anchor** round-trips as one: the two states are distinct on the wire,
        // so an ordinary fringe request cannot be read as a recovery sync that named block 0.
        let plain = FinalizedFringeRequest {
            anchor: None,
            ..req.clone()
        };
        let decoded = FinalizedFringeRequest::from_bytes(&plain.to_bytes()).unwrap();
        assert_eq!(decoded.anchor, None, "no anchor is not the zero hash");

        // **An anchor that is not a block hash is refused, not read as an absent one.** `anchor` is a
        // refinement, and a 31-byte value is a corrupt request rather than an ordinary one — reading it
        // as `None` would silently answer a different question (C259's whole failure mode).
        let short = FinalizedFringeRequestProto {
            identifier: "old".to_string(),
            trim_state: false,
            anchor: vec![0u8; 31],
            ..Default::default()
        };
        assert!(
            FinalizedFringeRequest::from_proto(&short).is_err(),
            "a malformed anchor must not decode as an ordinary fringe request"
        );

        // The defaults are **off**: a requester that does not know either field sends `false`/empty,
        // and the responder then sends no ancestry and answers from its own latest fringe — which is
        // what makes these non-breaking additions rather than a change every node makes at once.
        let proto = FinalizedFringeRequestProto {
            identifier: "old".to_string(),
            trim_state: false,
            ..Default::default()
        };
        let old = FinalizedFringeRequest::from_proto(&proto).expect("an ordinary request");
        assert!(!old.include_fringe_metadata);
        assert_eq!(old.anchor, None);
    }

    #[test]
    fn casper_message_block_round_trips() {
        let msg = CasperMessage::BlockMessage(empty_block());
        let proto = msg.to_proto();
        let decoded = CasperMessage::from_proto(&proto).unwrap();
        assert_eq!(decoded, msg);
    }

    #[test]
    fn store_items_message_round_trips() {
        let msg = StoreItemsMessage {
            start_path: vec![(Blake2b256Hash::from_bytes([1u8; 32]), None)],
            last_path: vec![(Blake2b256Hash::from_bytes([2u8; 32]), Some(3))],
            history_items: vec![(Blake2b256Hash::from_bytes([4u8; 32]), vec![5, 6])],
            data_items: vec![(Blake2b256Hash::from_bytes([7u8; 32]), vec![8])],
        };
        let decoded = StoreItemsMessage::from_bytes(&msg.to_bytes()).unwrap();
        assert_eq!(decoded, msg);

        let casper = CasperMessage::StoreItemsMessage(msg.clone());
        let proto = casper.to_proto();
        let decoded_casper = CasperMessage::from_proto(&proto).unwrap();
        assert_eq!(decoded_casper, casper);
    }

    #[test]
    fn store_items_message_request_round_trips() {
        let req = StoreItemsMessageRequest {
            start_path: vec![(Blake2b256Hash::from_bytes([9u8; 32]), Some(1))],
            skip: 2,
            take: 3,
        };
        let decoded = StoreItemsMessageRequest::from_bytes(&req.to_bytes()).unwrap();
        assert_eq!(decoded, req);

        let casper = CasperMessage::StoreItemsMessageRequest(req.clone());
        let proto = casper.to_proto();
        let decoded_casper = CasperMessage::from_proto(&proto).unwrap();
        assert_eq!(decoded_casper, casper);
    }

    fn signed_deploy_data(term: &str) -> SignedDeployData {
        use rchain_crypto::signatures::secp256k1::Secp256k1;
        use rchain_crypto::signatures::signatures_alg::SignaturesAlg;
        use rchain_crypto::signatures::signed::Signed;
        let (sec, _pk) = Secp256k1.new_key_pair();
        let data = DeployData {
            attachments: Vec::new(),
            term: term.to_string(),
            timestamp: 0,
            phlo_price: 1,
            phlo_limit: 100,
            valid_after_block_number: 0,
            shard_id: "root".to_string(),
        };
        let signed = Signed::new(data, &Secp256k1, &sec).unwrap();
        SignedDeployData {
            data: signed.data,
            deployer: signed.pk.bytes().to_vec(),
            sig: signed.sig,
            sig_algorithm: signed.sig_algorithm.name().to_string(),
        }
    }

    #[test]
    fn verify_signature_accepts_valid_deploy() {
        assert!(signed_deploy_data("Nil").verify_signature());
    }

    #[test]
    fn verify_signature_rejects_tampered_term() {
        let mut sd = signed_deploy_data("Nil");
        sd.data.term = "Nil | Nil".to_string();
        assert!(!sd.verify_signature());
    }

    #[test]
    fn verify_signature_rejects_unknown_algorithm() {
        let mut sd = signed_deploy_data("Nil");
        sd.sig_algorithm = "bogus".to_string();
        assert!(!sd.verify_signature());
    }

    fn signed_deploy_with_attachments(attachments: Vec<Vec<u8>>) -> SignedDeployData {
        use rchain_crypto::signatures::secp256k1::Secp256k1;
        use rchain_crypto::signatures::signatures_alg::SignaturesAlg;
        use rchain_crypto::signatures::signed::Signed;
        let (sec, _pk) = Secp256k1.new_key_pair();
        let data = DeployData {
            term: "Nil".to_string(),
            timestamp: 0,
            phlo_price: 1,
            phlo_limit: 100,
            valid_after_block_number: 0,
            shard_id: "root".to_string(),
            attachments,
        };
        let signed = Signed::new(data, &Secp256k1, &sec).unwrap();
        SignedDeployData {
            data: signed.data,
            deployer: signed.pk.bytes().to_vec(),
            sig: signed.sig,
            sig_algorithm: signed.sig_algorithm.name().to_string(),
        }
    }

    #[test]
    fn attachments_are_part_of_the_signature() {
        // RCHIP #39: attachments live in the signed deploy data, so neither tampering with nor
        // stripping them can pass verification.
        let sd = signed_deploy_with_attachments(vec![vec![1, 2, 3]]);
        assert!(sd.verify_signature());

        let mut tampered = sd.clone();
        tampered.data.attachments = vec![vec![9, 9, 9]];
        assert!(!tampered.verify_signature());

        let mut stripped = sd;
        stripped.data.attachments.clear();
        assert!(!stripped.verify_signature());
    }

    #[test]
    fn attachments_round_trip_proto_and_json() {
        let deploy = DeployData {
            term: "Nil".to_string(),
            timestamp: 0,
            phlo_price: 1,
            phlo_limit: 1,
            valid_after_block_number: 0,
            shard_id: "root".to_string(),
            attachments: vec![vec![1, 2, 3], vec![]],
        };

        // The proto round-trip preserves the attachments (including an empty one).
        let bytes = <DeployData as Serialize<DeployData>>::encode(&deploy);
        assert_eq!(
            <DeployData as Serialize<DeployData>>::decode(&bytes).unwrap(),
            deploy
        );

        // JSON carries them as hex strings, and an ordinary deploy omits the field entirely.
        let json = serde_json::to_value(&deploy).unwrap();
        assert_eq!(json["attachments"], serde_json::json!(["010203", ""]));
        assert_eq!(serde_json::from_value::<DeployData>(json).unwrap(), deploy);

        let mut plain = deploy;
        plain.attachments.clear();
        assert!(serde_json::to_value(&plain)
            .unwrap()
            .get("attachments")
            .is_none());
    }

    #[test]
    fn total_phlo_charge_does_not_wrap_on_overflow() {
        let mut d = DeployData {
            attachments: Vec::new(),
            term: "Nil".to_string(),
            timestamp: 0,
            phlo_price: i64::MAX,
            phlo_limit: 2,
            valid_after_block_number: 0,
            shard_id: "root".to_string(),
        };
        assert_eq!(d.total_phlo_charge(), None);

        d.phlo_limit = 1;
        assert_eq!(
            d.total_phlo_charge(),
            Some(NonNegI64::try_from(i64::MAX).unwrap())
        );

        d.phlo_limit = 0;
        assert_eq!(d.total_phlo_charge(), Some(NonNegI64::zero()));

        // The sign, which this test did not cover until AUDIT C109: an overflow is not the only way a
        // charge can be unusable. A negative limit (or a negative price) is a *mint* if it reaches the
        // charge path, so it must be refused here, at the boundary, rather than at each caller.
        d.phlo_price = 1;
        d.phlo_limit = -100;
        assert_eq!(
            d.total_phlo_charge(),
            None,
            "a negative charge must not be representable"
        );

        d.phlo_price = -1;
        d.phlo_limit = 100;
        assert_eq!(
            d.total_phlo_charge(),
            None,
            "a negative price must not yield a usable charge"
        );
    }

    /// The refund's clamp, at the end the old code did not have (AUDIT C109). `refund_amount`'s doc
    /// claimed the result was "non-negative by construction" while `phlo_price` came straight off the
    /// wire; a negative price made a negative refund. Pinned at both ends now, because the claim is
    /// only worth making if a failing input can reach it.
    #[test]
    fn refund_amount_is_non_negative_for_every_input() {
        let mut d = DeployData {
            attachments: Vec::new(),
            term: "Nil".to_string(),
            timestamp: 0,
            phlo_price: 1,
            phlo_limit: 100,
            valid_after_block_number: 0,
            shard_id: "root".to_string(),
        };
        let mut processed = ProcessedDeploy {
            deploy: SignedDeployData {
                data: d.clone(),
                deployer: Vec::new(),
                sig: Vec::new(),
                sig_algorithm: String::new(),
            },
            cost: PCost { cost: 40 },
            deploy_log: Vec::new(),
            is_failed: false,
            system_deploy_error: None,
        };
        assert_eq!(i64::from(processed.refund_amount()), 60);

        // A negative price can no longer produce a negative refund.
        d.phlo_price = -1;
        processed.deploy.data = d;
        assert_eq!(i64::from(processed.refund_amount()), 0);

        // A negative limit cannot either, and must not borrow from the remaining-cost clamp.
        processed.deploy.data.phlo_price = 1;
        processed.deploy.data.phlo_limit = -100;
        assert_eq!(i64::from(processed.refund_amount()), 0);
    }

    /// **The equivocation evidence round-trips, and every field is checked on ingress** (AUDIT C200).
    ///
    /// The decode is the boundary between a proposer's bytes and a signature verification, so a field
    /// that is the wrong length has to be refused *here* rather than reaching a slice or an assert: a
    /// 31-byte "hash" that got through would be verified against a key it cannot belong to, and the
    /// verifier would answer `false` for a reason that has nothing to do with the offence. `decode` is
    /// also what makes `is_signed_by` total, since the hash it reads is a real one by then.
    #[test]
    fn equivocation_evidence_round_trips_and_refuses_a_malformed_field() {
        let evidence = EquivocationEvidence {
            block_hash: BlockHash::new([7u8; 32]),
            sender: Validator::new([9u8; 65]),
            seq_num: SeqNum::try_from(12).unwrap(),
            sig: vec![1, 2, 3],
            sig_algorithm: "secp256k1".to_string(),
        };
        assert_eq!(
            EquivocationEvidence::decode(&evidence.encode()).unwrap(),
            evidence,
            "the wire form carries every field, including the ones the verifier reads"
        );

        // A hash that is not 32 bytes: refused by the constructor, not by an assert further in.
        let short_hash = EquivocationEvidenceProto {
            block_hash: vec![7u8; 31],
            ..Default::default()
        };
        assert!(EquivocationEvidence::decode(&short_hash.encode_to_vec()).is_err());

        // A sender that is not a 65-byte key: the same, and this is the field `is_signed_by` reads
        // first, so a short one would otherwise be compared against a key of another length.
        let short_sender = EquivocationEvidenceProto {
            block_hash: vec![7u8; 32],
            sender: vec![9u8; 64],
            ..Default::default()
        };
        assert!(EquivocationEvidence::decode(&short_sender.encode_to_vec()).is_err());

        // Bytes that are not the message at all.
        assert!(EquivocationEvidence::decode(b"not evidence").is_err());
    }
}
